const subjectCommon = bindCommon;
home = function(){let next=topics.find(t=>t.id===progress.last)||topics[0];return `<div class="book-kicker"><span>${siteConfig.short} · A VISUAL ENGINEERING FIELD GUIDE</span><span class="scribble">for the “wait… why?” kind of mind ↙</span></div><section class="notebook-hero"><div class="hero-copy"><span class="yellow-tape">Big engineering ideas. Little everyday stories.</span><h1>${siteConfig.title}</h1><p>${siteConfig.description}</p><p><strong>See the idea first. Learn its real name next.</strong></p><div class="row"><a class="btn primary" href="#lesson/${progress.visited.length?next.id:siteConfig.start}">${progress.visited.length?'Pick up where you left off':'Open the first visual story'} →</a><a class="text-link" href="#course">Flip through all ${topics.length} topics ↗</a></div><div class="hero-pencil-note">See it. Predict it. Try it. <span>Make it click.</span>${pencilArrow()}</div></div><div class="hero-scrap subject-demo"><div class="torn-label">${siteConfig.demoTitle}</div><div class="subject-demo-stage"><svg id="subjectDemoSvg" viewBox="0 0 420 290" role="img" aria-label="Interactive ${siteConfig.short} demonstration"></svg></div><div id="subjectDemoControls" class="pancake-controls"></div><p id="subjectDemoCaption" class="scribble" role="status">${siteConfig.demoCaption}</p><span class="stamp-note">A CONCEPTUAL MODEL · YOU CONTROL THE NEXT MOVE</span></div></section><div class="notebook-divider"><span>How the idea gets into your head</span></div><section class="learn-method"><article><span class="scribble method-number">01.</span><h3>Start with a familiar story.</h3><p>Meet a tiny switch, a helpful clerk, or a snapshot notebook before the technical terms arrive.</p></article><article><span class="scribble method-number">02.</span><h3>Watch your topic unfold.</h3><p>Every lesson has a worked animation. Pause, rewind, predict, and tap objects to inspect the current move.</p></article><article><span class="scribble method-number">03.</span><h3>Put your brain to work.</h3><p>Arrange the steps, uncover a pitfall, answer three checks, and explain it in your own words.</p></article></section><div class="section-head book-contents-head"><div><span class="scribble red-note">Your next “aha!” lives somewhere in here ↓</span><h2>The book of ${siteConfig.short} discoveries</h2><p>${topics.length} original lessons. Clear beginnings. Engineering depth.</p></div><a class="text-link" href="#course">Open the contents →</a></div><section class="book-chapters">${chapterInfo.map((c,i)=>`<a class="book-chapter" href="#course/${i}"><span class="chapter-big">${String(i+1).padStart(2,'0')}</span><div><h3>${c[0]}</h3><p>${c[1]}</p><span class="chapter-preview">${topics.filter(t=>t.chapter===i).slice(0,3).map(t=>t.title).join(' · ')}…</span></div><span class="scribble">${topics.filter(t=>t.chapter===i).length} ideas ↗</span></a>`).join('')}</section><div class="sticky-question"><span class="scribble">What if I’m a total beginner?</span><p>Start with the everyday story. We’ll connect the technical terms after the idea makes sense.</p><a class="text-link" href="#lesson/foundations">Open page one →</a></div><p class="source-note">Go deeper with the primary references: ${siteConfig.sources.map(([title,url])=>`<a href="${url}" target="_blank" rel="noopener">${title}</a>`).join(' · ')}. The explanations and illustrations in this site are original.</p>`};
cheatsheet = function(){return `<div class="page-intro"><span class="yellow-tape">Your ${siteConfig.short} revision notebook</span><h1>Less to memorize.<br>More to connect.</h1><p>Engineering notes, use cases, and the full story one click away.</p><button class="btn" id="printSheet">Print / save as PDF ↗</button></div><label for="sheetFilter" class="visually-hidden">Filter revision notes</label><input id="sheetFilter" class="filter-input" placeholder="Filter by topic, idea, or use case…"><div class="table-wrap"><table><thead><tr><th>Idea</th><th>Engineering note</th><th>Use it for</th></tr></thead><tbody id="sheetRows">${topics.map(t=>`<tr><td><a href="#lesson/${t.id}">${esc(t.title)} ↗</a></td><td>${esc(t.cost)}</td><td>${esc(t.use)}</td></tr>`).join('')}</tbody></table></div><p class="source-note">Primary references: ${siteConfig.sources.map(([title,url])=>`<a href="${url}" target="_blank" rel="noopener">${title}</a>`).join(' · ')}. Tool examples depend on the stated project and environment.</p>`};
function demoBox(x,y,w,h,label,active=false){return `<g class="demo-object ${active?'demo-active':''}"><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3"/><text x="${x+w/2}" y="${y+h/2+5}" text-anchor="middle">${esc(label)}</text></g>`}
function demoLine(x,y,x2,y2,active=false){return `<path d="M${x} ${y}L${x2} ${y2}" class="demo-line ${active?'demo-line-active':''}"/>`}
function inverterDemo(){let a=0;const svg=$('#subjectDemoSvg');function draw(){svg.innerHTML=`<text class="demo-hand" x="210" y="23" text-anchor="middle">Two switches. Opposite jobs.</text><text x="235" y="52" text-anchor="middle">VDD (high rail)</text>${demoLine(225,60,225,87,!a)}${demoLine(225,130,225,164,!a)}${demoLine(225,164,330,164,true)}${demoLine(225,164,225,190,!!a)}${demoLine(225,233,225,259,!!a)}${demoLine(75,164,135,164,true)}${demoLine(135,110,135,212,true)}${demoLine(135,110,166,110,!a)}${demoLine(135,212,166,212,!!a)}<circle cx="164" cy="110" r="5" stroke="#554735" fill="#fffdf4"/>${demoBox(175,88,101,43,'PMOS '+(!a?'ON':'OFF'),!a)}${demoBox(175,190,101,43,'NMOS '+(a?'ON':'OFF'),!!a)}${demoBox(9,141,68,46,'A = '+a,true)}${demoBox(330,141,78,46,'Y = '+(1-a),true)}<path d="M205 260h40m-34 6h28m-22 6h16" stroke="#655a43" fill="none"/><text class="demo-hand" x="330" y="216" text-anchor="middle">${a?'pulled low':'pulled high'}</text>`;$('#subjectDemoCaption').textContent=a?'A is high: NMOS pulls down. Output Y is low.':'A is low: PMOS pulls up. Output Y is high.'}$('#subjectDemoControls').innerHTML='<button class="btn primary" id="flipInput">Flip input A ↔</button><button class="btn" id="resetDemo">Reset ↺</button>';$('#flipInput').onclick=()=>{a=1-a;draw()};$('#resetDemo').onclick=()=>{a=0;draw()};draw()}
function cpuDemo(){let step=0;const labels=['Fetch','Decode','Execute','Writeback'],messages=['Fetch ADD x3,x1,x2 from the instruction stream.','Decode: source x1 is 5, source x2 is 7, destination is x3.','Execute: the ALU calculates 5 + 7 = 12.','Writeback: x3 receives 12. The visible register state changes.'];function draw(){const active=Math.min(step,3);$('#subjectDemoSvg').innerHTML=`<text class="demo-hand" x="210" y="25" text-anchor="middle">What happens inside one ADD?</text>${labels.map((l,i)=>demoBox(15+i*102,60,86,45,l,active===i)).join('')}${[0,1,2].map(i=>demoLine(101+i*102,82,117+i*102,82,step>i)).join('')}${demoBox(35,153,100,53,'x1 = 5')}${demoBox(160,153,100,53,'x2 = 7')}${demoBox(285,153,100,53,'x3 = '+(step>=3?12:0),step>=3)}<text class="demo-hand" x="210" y="253" text-anchor="middle">${step<2?'source values stay the same':step===2?'ALU result = 12':'The answer has a home.'}</text>`;$('#subjectDemoCaption').textContent=messages[active];$('#cpuNext').textContent=step>=3?'Run it again ↺':'Next processor move →'}$('#subjectDemoControls').innerHTML='<button class="btn primary" id="cpuNext">Next processor move →</button><button class="btn" id="resetDemo">Reset ↺</button>';$('#cpuNext').onclick=()=>{step=(step+1)%4;draw()};$('#resetDemo').onclick=()=>{step=0;draw()};draw()}
function gitDemo(){let work=1,index=1,head=1,commits=0;function draw(msg){$('#subjectDemoSvg').innerHTML=`<text class="demo-hand" x="210" y="26" text-anchor="middle">A commit saves the tray, not the desk.</text>${demoBox(8,65,120,75,'Work v'+work,work!==index)}${demoBox(150,65,120,75,'Index v'+index,index!==head)}${demoBox(292,65,120,75,'HEAD v'+head)}${demoLine(129,102,150,102,true)}${demoLine(271,102,292,102,true)}<text x="69" y="166" text-anchor="middle">editable desk</text><text x="210" y="166" text-anchor="middle">staging tray</text><text x="352" y="166" text-anchor="middle">saved snapshot</text><text class="demo-hand" x="210" y="224" text-anchor="middle">${commits} new commits · ${work===head?'work matches saved snapshot':'working tree still has another version'}</text>`;$('#subjectDemoCaption').textContent=msg}$('#subjectDemoControls').innerHTML='<button class="btn" id="gitEdit">1. Edit</button><button class="btn" id="gitStage">2. Stage</button><button class="btn primary" id="gitCommit">3. Commit</button><button class="btn" id="resetDemo">↺</button>';$('#gitEdit').onclick=()=>{work++;draw('Edited the desk version to v'+work+'. The staging tray did not change.')};$('#gitStage').onclick=()=>{index=work;draw('git add stages the current v'+index+'. Edit again to see what a commit will leave out.')};$('#gitCommit').onclick=()=>{if(index===head){draw('Nothing new is staged. A normal commit has no snapshot change to record here.');return}head=index;commits++;draw('Committed staged v'+head+'. '+(work===head?'The desk matches it.':'Desk v'+work+' remains an unstaged change.'))};$('#resetDemo').onclick=()=>{work=index=head=1;commits=0;draw(siteConfig.demoCaption)};draw(siteConfig.demoCaption)}
bindCommon=function(){subjectCommon();if($('#subjectDemoSvg')){if(siteConfig.short==='VLSI')inverterDemo();else if(siteConfig.short==='µCPU')cpuDemo();else gitDemo()}};
const subjectRoute=route;route=function(){subjectRoute();document.title=(currentTopic?currentTopic.title:'A visual learning adventure')+' — '+siteConfig.name;document.body.dataset.subject=siteConfig.short;};window.removeEventListener('hashchange',subjectRoute);window.addEventListener('hashchange',route);route();
